using System;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.UIElements;
public static class UiOrderAcceptance {public static object Main(){const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;var type=typeof(EchoSphere.Runtime.EchoSphereRuntime).Assembly.GetType("EchoSphere.Presentation.NativeUiOrder");var method=type.GetMethod("InFront",F);int checks=0;for(int from=0;from<6;from++)for(int at=0;at<6;at++){if(from==at)continue;var p=new VisualElement();var nodes=Enumerable.Range(0,6).Select(i=>new VisualElement{name="e"+i}).ToArray();foreach(var n in nodes)p.Add(n);nodes[from].PlaceInFront(nodes[at]);var expected=p.Children().Select(n=>n.name).ToArray();p.Clear();foreach(var n in nodes)p.Add(n);method.Invoke(null,new object[]{nodes[from],nodes[at]});if(!p.Children().Select(n=>n.name).SequenceEqual(expected))throw new Exception("order mismatch");for(int i=0;i<100;i++)method.Invoke(null,new object[]{nodes[from],nodes[at]});if(!p.Children().Select(n=>n.name).SequenceEqual(expected))throw new Exception("repeated order mismatch");checks++;}var go=new GameObject("UI order version acceptance");var settings=ScriptableObject.CreateInstance<PanelSettings>();var doc=go.AddComponent<UIDocument>();doc.panelSettings=settings;var parent=doc.rootVisualElement;var a=new VisualElement();var b=new VisualElement();parent.Add(a);parent.Add(b);var ptype=parent.panel.GetType();var version=ptype.GetProperty("hierarchyVersion",F);var v0=Convert.ToInt64(version.GetValue(parent.panel));for(int i=0;i<100;i++)method.Invoke(null,new object[]{b,a});var v1=Convert.ToInt64(version.GetValue(parent.panel));if(v0!=v1)throw new Exception("unchanged order invalidates hierarchy");for(int i=0;i<100;i++)b.PlaceInFront(a);var v2=Convert.ToInt64(version.GetValue(parent.panel));if(v2<=v1)throw new Exception("reference no longer demonstrates churn");checks++;var props=ptype.GetProperties(F).Where(p=>p.Name.ToLowerInvariant().Contains("version")).Select(p=>p.Name+"="+p.GetValue(parent.panel)).ToArray();UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(settings);return new{result="PASS",checks,guardedHierarchyChanges=v1-v0,referenceHierarchyChanges=v2-v1,panelVersions=props};}}
